-- Migration 0098: Canvas media objects and media tracks (metadata only).
--
-- Canvas models (`app/models/media_object.rb`, `app/models/media_track.rb`):
--
--   media_objects
--     A media entry owned by a user. `media_id` is the opaque Kaltura entry id
--     (`m-...`); no binary content is stored here. `title` is the provider
--     supplied name, `user_entered_title` the user override (max 255 chars).
--   media_tracks
--     Captions/subtitles attached to a media object. `external_id` marks a
--     track generated by ASR (`MediaTrack#asr?` = subtitles + external_id).
--
-- Routes served by star-media:
--   GET/POST /media_attachments
--   PUT      /media_attachments/{id}
--   GET      /media_objects/{id}/media_tracks

CREATE TABLE IF NOT EXISTS media_objects (
    id                BIGSERIAL PRIMARY KEY,
    media_id          TEXT NOT NULL UNIQUE,
    media_type        TEXT NOT NULL DEFAULT 'video', -- video | audio
    title             TEXT,
    user_entered_title TEXT,
    user_id           BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    workflow_state    TEXT NOT NULL DEFAULT 'active', -- active | deleted
    created_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at        TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Listing is scoped to the requesting user (Canvas `index`).
CREATE INDEX IF NOT EXISTS idx_media_objects_user
    ON media_objects(user_id, workflow_state);

CREATE TABLE IF NOT EXISTS media_tracks (
    id              BIGSERIAL PRIMARY KEY,
    media_object_id BIGINT NOT NULL REFERENCES media_objects(id) ON DELETE CASCADE,
    user_id         BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    kind            TEXT NOT NULL DEFAULT 'subtitles', -- subtitles | captions | descriptions | chapters | metadata
    locale          TEXT NOT NULL DEFAULT 'en',
    content         TEXT,
    external_id     TEXT,
    workflow_state  TEXT NOT NULL DEFAULT 'active', -- active | deleted
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_media_tracks_media_object
    ON media_tracks(media_object_id, user_id);
